import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric,
  getRegisteredMetricIds
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function getRegisteredMetricIds() {
  return DEFAULT_METRICS.map((metric) => {
    if (typeof metric === 'function') return metric.id;
    if (metric && typeof metric.id === 'string') return metric.id;
    return null;
  }).filter(Boolean);
}

export function validateThresholds(thresholds, registeredIds) {
  if (!thresholds || typeof thresholds !== 'object' || Array.isArray(thresholds)) {
    return { valid: true, errors: [] };
  }

  const errors = [];
  const ids = registeredIds || getRegisteredMetricIds();

  for (const [key, value] of Object.entries(thresholds)) {
    if (typeof value !== 'number') {
      errors.push(formatThresholdError('format_error', key, ids));
      continue;
    }

    if (value < 0.0 || value > 1.0) {
      errors.push(formatThresholdError('range_error', value, ids));
      continue;
    }

    if (!ids.includes(key)) {
      errors.push(formatThresholdError('unknown_metric', key, ids));
    }
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

export function formatThresholdError(type, value, validIds = []) {
  switch (type) {
    case 'format_error':
      return `Threshold format must be <metric>=<number>, got: ${value}`;
    case 'range_error':
      return `Threshold minimum must be between 0.0 and 1.0, got: ${value}`;
    case 'unknown_metric':
      return `Unknown metric: '${value}'. Valid metric IDs: ${validIds.join(', ')}`;
    default:
      return `Invalid threshold: ${value}`;
  }
}

export function evaluateThresholds(thresholds, evaluations) {
  if (!thresholds || typeof thresholds !== 'object') {
    return [];
  }

  const metricsMap = {};
  for (const metric of evaluations) {
    if (metric && metric.id) {
      metricsMap[metric.id] = metric;
    }
  }

  const results = [];
  for (const [metricId, min] of Object.entries(thresholds)) {
    const metric = metricsMap[metricId];
    const score = metric ? metric.score : null;
    const passed = score !== null && score !== undefined && score >= min;

    results.push({
      metric: metricId,
      min,
      score,
      passed
    });
  }

  return results;
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && typeof thresholds === 'object' && !Array.isArray(thresholds)) {
    const validation = validateThresholds(thresholds, getRegisteredMetricIds());
    if (!validation.valid) {
      throw new Error(validation.errors[0]);
    }

    const thresholdResults = evaluateThresholds(thresholds, evaluations);
    report.passed = thresholdResults.every((t) => t.passed);
    report.thresholds = thresholdResults;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric,
  getRegisteredMetricIds
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  validateThresholds,
  evaluateThresholds,
  formatThresholdError,
  getRegisteredMetricIds,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

